verify:
def skill():
    cnt = 0
    m = 1
    while 2*m*(m + 1) <= 2000:
        cnt += 1
        m += 1
    return cnt

def standard():
    cnt = 0
    for n in range(1, 2001):
        # 합 = (sqrt(2n+1) - 1)/2 가 자연수인지: 2n+1이 제곱수이고 그 근이 홀수(3 이상)
        t = 2*n + 1
        r = math.isqrt(t)
        if r*r == t and (r - 1) % 2 == 0 and (r - 1)//2 >= 1:
            cnt += 1
    # 정의대로 합을 직접 계산해 몇 개만 확인
    for n in (1, 4, 12):
        s = sum(1/(sqrt(2*k - 1) + sqrt(2*k + 1)) for k in range(1, n + 1))
        assert abs(N(s) - N((sqrt(2*n + 1) - 1)/2)) < 1e-12
    return cnt

def unique():
    return [standard()]
